{
  "packages": {
    "ui": {
      "role": "Component library — reusable React UI components built with Radix UI and Tailwind CSS.",
      "depends_on": []
    },
    "web-core": {
      "role": "Shared feature library — domain logic, routing, database integration, and reusable React features used by both local and remote web apps.",
      "depends_on": ["ui"]
    },
    "local-web": {
      "role": "Local desktop web app entrypoint — Vite-based React app for the Tauri client.",
      "depends_on": ["web-core", "ui"]
    },
    "remote-web": {
      "role": "Remote deployment web app entrypoint — Vite-based React app for cloud deployment.",
      "depends_on": ["web-core", "ui"]
    },
    "shared": {
      "role": "Generated type definitions and agent tool schemas — auto-generated from Rust (types.ts, remote-types.ts) and shared schemas.",
      "depends_on": []
    }
  },
  "direction": "Foundation-up: ui and shared are independent roots; web-core builds on ui; local-web and remote-web converge on web-core and ui."
}
```

